from concurrent.futures import ThreadPoolExecutor
from PIL import Image,ImageOps
from produce import EP,request,save
OUT=EP/'image/character-options/v3';OUT.mkdir(parents=True,exist_ok=True)
BASE='''Character design illustration, ONE clearly stylized ANIMATED adult Chinese male cleaner around 38, full body, entire shoes and head inside frame. This is a CARTOON CHARACTER DESIGN, not a realistic human portrait. Deliberately stylized proportions: head noticeably larger, body about FIVE AND A HALF heads tall, compact torso, simplified limbs with actual volume, larger simple gloved hands and chunky practical work shoes. Mature approachable ordinary tradesman. Short black hair shaped into only 4-5 large sculpted graphic tufts. Face constructed with large simple shapes: broad cheek silhouette, expressive medium-sized eyes, thick simple eyebrows, small simple nose, short mouth; NO realistic cheekbones, facial anatomy lines, wrinkles, nasolabial folds, pores, stubble or detailed eyelids. Clearly drawn animated face, not realistic face with an outline. Muted teal-blue practical work jacket with only two pockets and THREE OR FOUR broad folds total, dark charcoal trousers, yellow cleaning gloves. Simplified fabric surfaces, NO dense realistic wrinkle texture. Natural three-quarter standing pose, hands relaxed, calm slightly curious expression. Traditional hand-painted animated-film visual language with warm fine pencil outlines, opaque gouache color shapes, simple soft shadows, gentle brush edges. Enough painted light to blend into room, NOT photorealistic, NOT gritty comic, NOT realistic anatomy study, NOT glossy 3D render, NOT white round stick figure, NOT huge glittery anime eyes or idol teenager. Keep visibly CARTOON head proportions and stylized shapes. Reference image is environment painting and light only, do not derive realistic human anatomy from room. Same old sea-green tiled kitchen and window light, environment softly simplified into broad painted shapes without losing room identity; camera framing portrait-focused with character filling 85 percent height, enough quiet space around silhouette. Single full-frame 16:9 landscape, no text, labels, logos, panels, duplicated figures or extra props. '''
OPTIONS=[('F','成年动漫造型','Face slightly angular but soft, short swept hair in chunky tufts, eyes clearly drawn larger and simpler than realistic, sturdy shoulders and compact silhouette. Maintain adult working-man personality, subtle reserved half smile.'),('G','圆润动画造型','Face broad and gently rounded, bigger expressive eyebrows, soft rectangular nose, short cropped hair as one dark shape with few large tufts, stocky compact working-man silhouette, quietly dependable expression. Strong appealing hand-drawn animation shape language.')]
def gen(pair):
 i,(key,name,desc)=pair;bg=EP/'image/backgrounds/kitchen-full.png';src=request('worker-cartoon-'+key.lower(),BASE+desc,i,bg,dict(stage='character-design-candidate',option=key,name=name,user_direction='人物造型明确动漫化，不是减少写实细节',reference_roles={str(bg):'environment painting and light only'}));out=OUT/f'清理垃圾屋_主角{key}_{name}.png'
 with Image.open(src) as im:ImageOps.fit(im.convert('RGB'),(1920,1080),method=Image.Resampling.LANCZOS).save(out)
 return dict(option=key,name=name,file=str(out.relative_to(EP)))
with ThreadPoolExecutor(max_workers=2) as pool:rows=list(pool.map(gen,enumerate(OPTIONS)))
save(EP/'qa/character-options-current.json',dict(status='待目检',direction='五头半身成年动漫角色造型',options=rows));print('READY',flush=True)
